import Link from "next/link";
import { ArrowRight, Gauge } from "lucide-react";
import type { QuotaAllowance, QuotaSnapshot } from "@/lib/quota-snapshot";
import { cn } from "@/lib/utils";

const valueClass = "text-[var(--allowance-value)] text-[14px] font-bold";

function AllowanceMeter({
  label,
  allowance,
  segmented = false,
}: {
  label: "Daily" | "Monthly";
  allowance: QuotaAllowance;
  segmented?: boolean;
}) {
  const limit = Math.max(0, allowance.limit);
  const remaining = Math.max(0, Math.min(limit, allowance.remaining));
  const ratio = limit > 0 ? remaining / limit : 0;
  const low = remaining > 0 && (ratio <= 0.1 || (segmented && remaining === 1));
  return (
    <div className="grid gap-[3px] min-w-0">
      <span className="text-[var(--allowance-label)] [font:500_10px/1.2_var(--font-jetbrains),_monospace] tracking-[0.14em] uppercase">
        {label}
      </span>
      {label === "Monthly" && !allowance.startsAt ? (
        <span className="max-w-35 text-[11px]">
          Monthly allowance unavailable
        </span>
      ) : (
        <div className="flex items-center gap-2.5 [@media(max-width:_639px)]:flex-col [@media(max-width:_639px)]:items-start [@media(max-width:_639px)]:gap-[5px]">
          <span
            className={`whitespace-nowrap [font-variant-numeric:tabular-nums]`}
          >
            <strong
              className={cn(
                valueClass,
                remaining === 0 && "text-[var(--status-error-text)]",
              )}
            >
              {remaining}
            </strong>{" "}
            <span>/ {limit} left</span>
          </span>
          <div
            className={cn(
              "shrink-0",
              segmented
                ? "flex gap-[3px]"
                : "w-14 h-[var(--allowance-bar-height)] rounded-[var(--allowance-meter-radius)] [background:var(--allowance-track)]",
            )}
            role="meter"
            aria-label={`${label} emails left`}
            data-low={low || undefined}
            aria-valuemin={0}
            aria-valuemax={limit}
            aria-valuenow={remaining}
          >
            {segmented ? (
              Array.from({ length: limit }, (_, index) => (
                <span
                  key={index}
                  data-filled={index < remaining}
                  className={cn(
                    "w-3 h-1 rounded-[var(--allowance-meter-radius)] [background:var(--allowance-track)]",
                    index < remaining &&
                      (low
                        ? "[background:var(--status-warning-text)] shadow-none"
                        : "[background:var(--allowance-fill)] shadow-[var(--allowance-meter-shadow)]"),
                  )}
                />
              ))
            ) : (
              <span
                className={cn(
                  "block h-full rounded-[inherit]",
                  low
                    ? "[background:var(--status-warning-text)] shadow-none"
                    : "[background:var(--allowance-fill)] shadow-[var(--allowance-meter-shadow)]",
                )}
                style={{
                  width: `${ratio * 100}%`,
                  boxShadow: remaining === 0 ? "none" : undefined,
                }}
              />
            )}
          </div>
        </div>
      )}
    </div>
  );
}

// The same shell is rendered on the server while History is loading.
export function AllowancePillView({ quota }: { quota?: QuotaSnapshot }) {
  return (
    <section
      className="flex items-center flex-wrap gap-3 max-w-full min-w-0 min-h-14 py-[5px] pl-3 pr-1.5 border border-[var(--allowance-border)] rounded-full [background:var(--allowance-surface)] shadow-[var(--allowance-shadow)] text-[var(--allowance-muted)] [font-family:var(--font-limit-banner,var(--font-plus-jakarta)),sans-serif] text-[13px] leading-[1.4] workspace-mono:rounded-[16px] min-[1024px]:flex-nowrap min-[1024px]:h-14 [@media(max-width:_639px)]:grid [@media(max-width:_639px)]:grid-cols-[32px_minmax(0,1fr)] [@media(max-width:_639px)]:gap-x-2 [@media(max-width:_639px)]:w-full [@media(max-width:_639px)]:p-3 [@media(max-width:_639px)]:rounded-[24px]"
      aria-label="Email allowances"
      aria-busy={!quota || undefined}
    >
      <span
        className={`workspace-mono:rounded-[8px] grid place-items-center shrink-0 w-8 h-8 rounded-[10px] [background:var(--allowance-icon-background)] text-[var(--allowance-icon)]`}
        aria-hidden="true"
      >
        <Gauge size={16} strokeWidth={1.8} />
      </span>
      <div className="flex items-center gap-3.5 min-w-0 [@media(max-width:_639px)]:justify-between [@media(max-width:_639px)]:gap-2">
        {!quota ? (
          <>
            <span className="sr-only">Loading email allowances…</span>
            {(["Daily", "Monthly"] as const).map((label, index) => (
              <div
                className="flex items-center gap-3.5 min-w-0 [@media(max-width:_639px)]:gap-2"
                key={label}
              >
                {index > 0 && (
                  <span className="shrink-0 w-[1px] h-5.5 border-l border-dotted border-separator" />
                )}
                <div className="grid gap-[3px] min-w-0">
                  <span className="text-[var(--allowance-label)] [font:500_10px/1.2_var(--font-jetbrains),_monospace] tracking-[0.14em] uppercase">
                    {label}
                  </span>
                  <div
                    className="flex items-center gap-2.5 [@media(max-width:_639px)]:flex-col [@media(max-width:_639px)]:items-start [@media(max-width:_639px)]:gap-[5px]"
                    aria-hidden="true"
                  >
                    <span
                      data-slot="allowance-placeholder-number"
                      className="block [background:var(--skeleton-base)] rounded-[var(--allowance-meter-radius)] w-19 h-4.5"
                    />
                    <span
                      data-slot="allowance-placeholder-meter"
                      className="block [background:var(--skeleton-base)] rounded-[var(--allowance-meter-radius)] w-14 h-[var(--allowance-bar-height)]"
                    />
                  </div>
                </div>
              </div>
            ))}
          </>
        ) : quota.mode === "legacy" ? (
          <span className="wrap-anywhere">
            <strong className={valueClass}>
              {Math.max(0, quota.limit - quota.used)}
            </strong>{" "}
            remaining per rolling 24 hours
          </span>
        ) : !quota.sendingAllowed ? (
          <span className="wrap-anywhere">Sending paused.</span>
        ) : (
          <>
            <AllowanceMeter
              label="Daily"
              allowance={quota.daily}
              segmented={quota.plan === "FREE"}
            />
            <span
              className="shrink-0 w-[1px] h-5.5 border-l border-dotted border-separator"
              aria-hidden="true"
            />
            <AllowanceMeter label="Monthly" allowance={quota.monthly} />
          </>
        )}
      </div>
      <Link
        href="/usage#allowances"
        className={`workspace-mono:rounded-[10px] hover:[background:var(--allowance-button-hover)] hover:text-[var(--allowance-value)] focus-visible:outline-2 focus-visible:outline-[var(--appearance-focus,var(--ring))] focus-visible:outline-offset-[3px] inline-flex items-center justify-center shrink-0 gap-1.5 min-h-11 py-0 px-3 rounded-full [background:var(--allowance-button)] text-[var(--allowance-button-text)] text-[13px] font-semibold no-underline whitespace-nowrap [@media(max-width:_639px)]:[grid-column:1_/_-1] [@media(max-width:_639px)]:w-full`}
      >
        View allowances{" "}
        <ArrowRight size={14} strokeWidth={1.8} aria-hidden="true" />
      </Link>
    </section>
  );
}
